def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    mine = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = mine[-1]
    last_opp = opp[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    recent10_d = sum(1 for o in opp[-10:] if o == 'D')
    recent6_d = sum(1 for o in opp[-6:] if o == 'D')

    if n >= 3 and opp_d == n:
        return 'D'
    if n >= 10 and recent10_d >= 8:
        return 'D'
    if n >= 12 and opp_d * 3 >= n * 2:
        return 'D'

    after_c_n = after_c_d = after_d_n = after_d_d = 0
    for i in range(n - 1):
        if mine[i] == 'C':
            after_c_n += 1
            if opp[i + 1] == 'D':
                after_c_d += 1
        else:
            after_d_n += 1
            if opp[i + 1] == 'D':
                after_d_d += 1

    if after_c_n > 0:
        p_c = after_c_d / after_c_n
    else:
        p_c = 0.35
    if after_d_n > 0:
        p_d = after_d_d / after_d_n
    else:
        p_d = 0.65

    if after_d_n >= 2 and p_d <= 0.25:
        return 'D'
    if after_c_n >= 4 and p_c >= 0.65:
        return 'D'

    if last_opp == 'C':
        if n >= 85 and opp_c >= opp_d and after_d_n >= 3 and p_d <= 0.35:
            return 'D'
        if 20 < n < 90 and recent6_d == 0 and opp_c >= opp_d:
            if after_d_n == 1 and p_d <= 0.25:
                return 'D'
            if rng.random() < 0.02:
                return 'D'
        return 'C'

    if last_me == 'D':
        if opp_d * 2 >= n or recent10_d >= 6 or (after_d_n >= 3 and p_d >= 0.6):
            return 'D'
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    if opp_d * 2 >= n or recent10_d >= 6 or (after_c_n >= 4 and p_c >= 0.55):
        return 'D'

    if n >= 2:
        prev_me, prev_opp = history[-2]
        if prev_me == 'D' and prev_opp == 'C':
            return 'C'

    if opp_c >= opp_d and recent6_d <= 1:
        if rng.random() < 0.6:
            return 'C'

    return 'D'
